(* Cost fixture: a package whose eight pure conjuncts cannot close, beside
   sixty pure facts that enter the context only when the package route
   splits the conjuncts off. Each split conjunct gets the finisher once; the
   sentence time is the cost of those failing attempts. *)
Lemma split_conjuncts_that_cannot_close `{!islaG Sigma} `{!threadG} : True.
Proof.
  Fail assert (Hsplit : forall (a b : Z) (R : iProp Sigma),
    ⌜(bv_unsigned (Z_to_bv 64 a) + 1 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 2 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 3 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 4 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 5 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 6 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 7 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 8 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 9 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 10 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 11 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 12 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 13 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 14 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 15 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 16 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 17 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 18 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 19 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 20 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 21 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 22 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 23 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 24 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 25 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 26 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 27 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 28 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 29 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 30 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 31 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 32 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 33 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 34 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 35 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 36 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 37 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 38 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 39 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 40 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 41 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 42 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 43 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64 a) + 44 <> b)%Z⌝ ∗ ⌜(bv_unsigned (Z_to_bv 64